import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int evens = 0;
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {
                System.out.println("第 " + i + " 圈是双数喵");
                evens = evens + 1;
            }
        }
        System.out.println("双数一共 " + evens + " 圈喵");
    }
}

